# Check left-right symmetry
for c in range(11):
    col1 = [demo_output[r][c] for r in range(20)]
    col2 = [demo_output[r][21-c] for r in range(20)]
    if col1 == col2:
        print(f"Col {c} == Col {21-c}")
    else:
        print(f"Col {c} vs {21-c} differ")

# Now let's think about the actual pattern transformation
# Input has 15x15 with dividers, output appears to have 24x22 with different structure

# Create full 15x15 output grid
# Using 4 7x7 quadrants + 1x15 dividing row + 15x1 dividing column

tl_pattern = [
    [3, 3, 2, 3, 3, 2, 3],
    [3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 2, 3, 3],
    [3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 2, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 2],
    [3, 3, 3, 2, 3, 3, 2],
]

try:
    tr_pattern = transposed_ccw_h_mirror
except:
    # Recalculate TR from TL
    tr_pattern = [[tl_pattern[6-x][y] for y in range(7)] for x in range(7)]

try:
    bl_pattern = transposed_ccw_v_mirror
except:
    # Recalculate BL from TL
    bl_pattern = [[tl_pattern[6-r][c] for c in range(7)] for r in range(7)]

# BR is same as BL for symmetry
try:
    br_pattern = transposed_ccv_mirror
except:
    br_pattern = [[tl_pattern[6-r][6-c] for c in range(7)] for r in range(7)]

# Build full 15x15 grid
output_15x15 = [[0]*15 for _ in range(15)]

# Fill TL (rows 0-6, cols 0-6)
for r in range(7):
    for c in range(7):
        output_15x15[r][c] = tl_pattern[r][c]

# Fill TR (rows 0-6, cols 8-14)
for r in range(7):
    for c in range(7):
        output_15x15[r][8+c] = tr_pattern[r][c]

# Fill BL (rows 8-14, cols 0-6)
for r in range(7):
    for c in range(7):
        output_15x15[8+r][c] = bl_pattern[r][c]

# Fill BR (rows 8-14, cols 8-14)
for r in range(7):
    for c in range(7):
        output_15x15[8+r][8+c] = br_pattern[r][c]

# Add dividers - row 7 and col 7 with value 4 (as in input)
for c in range(15):
    output_15x15[7][c] = 4
for r in range(15):
    output_15x15[r][7] = 4

print("Constructed 15x15 output grid:")
for r in range(15):
    print("".join(str(x) for x in output_15x15[r]))

